//! Parity tests for the MegaTTS3 aligner.
//!
//! Fixtures live in `testdata/megatts3_aligner/`, regenerated by
//! `tools/gen_megatts3_aligner_fixtures.py`:
//! - a tiny Whisper built from the reference classes (encoder output,
//!   teacher-forced logits, greedy decode);
//! - OpenAI's real `log_mel_spectrogram` on a synthetic waveform;
//! - scripted token streams pushed through the reference's real `align()`.
//!
//! A real converted checkpoint on real speech can be gated in with
//! TURBOSPARK_ALIGNER_MODEL (dir with `model.safetensors`) and
//! TURBOSPARK_ALIGNER_GOLDEN (dir with the `r_*.npy` traces from `--real-src`);
//! both are skipped when unset. Tests never download.

use std::path::{Path, PathBuf};

use super::aligner::{
    align_tokens, pad_prompt_audio, prompt_mel, resample_for_aligner, split_ph_timestamp, Aligner,
    AlignerConfig, BOS_TOKEN, EOS_TOKEN, MAX_NEW_TOKENS,
};
use super::tests::{f32s, i32s, max_diff};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/megatts3_aligner")
}

fn load_tiny() -> Aligner {
    let text = std::fs::read_to_string(testdata().join("tiny_config.json")).unwrap();
    let cfg = AlignerConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&testdata().join("tiny_weights.safetensors")).unwrap();
    Aligner::load(cfg, &file).unwrap()
}

#[test]
fn tiny_model_matches_pytorch() {
    let dir = testdata();
    let al = load_tiny();
    let mel = f32s(&dir, "tiny_mel.npy");
    let feats = al.encode(&mel, 40).unwrap();
    assert_eq!(feats.frames(), 20);
    let enc_diff = max_diff(feats.data(), &f32s(&dir, "tiny_feats.npy"));

    // Teacher-forced logits over every position: the cached incremental decode
    // must equal the reference's full-sequence recompute.
    let tokens = i32s(&dir, "tiny_tf_tokens.npy");
    let logits = al.logits_for(&feats, &tokens).unwrap();
    let logit_diff = max_diff(&logits, &f32s(&dir, "tiny_tf_logits.npy"));
    println!("tiny: encoder {enc_diff:e} logits {logit_diff:e}");
    assert!(enc_diff < 5e-6, "encoder diff {enc_diff}");
    assert!(logit_diff < 5e-6, "logits diff {logit_diff}");

    let greedy = al.generate(&feats, 24).unwrap();
    assert_eq!(greedy, i32s(&dir, "tiny_greedy.npy"), "greedy decode");
    assert_eq!(greedy[0], BOS_TOKEN);
}

#[test]
fn log_mel_matches_openai_whisper() {
    let dir = testdata();
    let wav = f32s(&dir, "mel_wav.npy");
    let (mel, frames) = prompt_mel(&wav).unwrap();
    assert_eq!(frames % 8, 0);
    let reference = f32s(&dir, "mel_ref.npy"); // [80, ref_frames] C-order
    let ref_frames = reference.len() / 80;
    assert!(frames <= ref_frames && ref_frames - frames < 8);
    let mut worst = 0.0f32;
    for m in 0..80 {
        for t in 0..frames {
            worst = worst.max((mel[m * frames + t] - reference[m * ref_frames + t]).abs());
        }
    }
    println!("mel: frames {frames}/{ref_frames} max diff {worst:e}");
    assert!(worst < 5e-5, "log-mel diff {worst}");
}

#[test]
fn scripted_streams_match_the_reference_align() {
    let dir = testdata();
    for tag in ["s1", "s2", "s3", "s4"] {
        let stream = i32s(&dir, &format!("{tag}_stream.npy"));
        let got = align_tokens(&stream, 200).unwrap();
        assert_eq!(
            got.phone,
            i32s(&dir, &format!("{tag}_ph.npy")),
            "{tag} phones"
        );
        assert_eq!(
            got.tone,
            i32s(&dir, &format!("{tag}_tone.npy")),
            "{tag} tones"
        );
        assert_eq!(
            got.mel2ph,
            i32s(&dir, &format!("{tag}_mel2ph.npy")),
            "{tag} mel2ph"
        );
        assert_eq!(got.mel2ph.len() % 8, 0);
    }
}

#[test]
fn phone_and_tone_token_mapping() {
    // Chinese tokens fold phone and tone: (id - 201) / 6 + 3, tone from the
    // remainder (0 -> 4, others +10). Everything else keeps its id with tone 3.
    let tokens = [
        200,
        800 + 10,
        201,
        800 + 20,
        206,
        800 + 30,
        207,
        800 + 40,
        788,
        800 + 50,
        199,
        800 + 60,
    ];
    let (ph, tone, dur) = split_ph_timestamp(&tokens).unwrap();
    assert_eq!(ph, vec![2, 3, 3, 4, 100, 199]);
    assert_eq!(tone, vec![15, 4, 15, 4, 15, 3]);
    assert_eq!(dur, vec![10, 10, 10, 10, 10, 10]);
}

#[test]
fn malformed_streams_are_errors() {
    assert!(
        split_ph_timestamp(&[10, 810, 20]).is_err(),
        "phone without a timestamp"
    );
    assert!(
        align_tokens(&[BOS_TOKEN, EOS_TOKEN], 8).is_err(),
        "too short"
    );
    assert!(
        align_tokens(&[BOS_TOKEN, 10, 810, 11, EOS_TOKEN], 8).is_err(),
        "truncated stream"
    );
    // Dropping the first and last token always applies, even without an EOS.
    let ok = align_tokens(&[BOS_TOKEN, 10, 808, 11, 816, 12], 16).unwrap();
    assert_eq!(ok.phone, vec![10, 11]);
}

#[test]
fn pad_prompt_audio_matches_preprocess() {
    let pad = |n: usize| pad_prompt_audio(&vec![0.5; n]).len();
    assert_eq!(pad(1000), 1199 + 12_000);
    assert_eq!(pad(1199), 1199 + 12_000); // remainder already 1199: no padding
    assert_eq!(pad(1200), 1200 + 1199 + 12_000);
    assert_eq!(pad(0), 1199 + 12_000);
    let p = pad_prompt_audio(&[0.25, -0.5]);
    assert_eq!(&p[..2], &[0.25, -0.5]);
    assert!(p[2..].iter().all(|&v| v == 0.0));
}

#[test]
fn prompt_mel_rejects_bad_audio() {
    assert!(prompt_mel(&[]).is_err());
    assert!(prompt_mel(&[0.0, f32::NAN, 0.1]).is_err());
    assert!(prompt_mel(&vec![0.0; 800]).is_err(), "under 8 frames");
}

#[test]
fn model_validates_inputs() {
    let al = load_tiny();
    let mel = f32s(&testdata(), "tiny_mel.npy");
    assert!(al.encode(&mel, 0).is_err());
    assert!(al.encode(&mel, 39).is_err(), "length mismatch");
    // enc_ctx is 64 positions = 128 mel frames.
    let long = vec![0.0f32; 80 * 130];
    assert!(al.encode(&long, 130).is_err(), "past the positional table");
    let feats = al.encode(&mel, 40).unwrap();
    assert!(
        al.logits_for(&feats, &[810]).is_err(),
        "token outside the vocabulary"
    );
    assert!(al.logits_for(&feats, &[-1]).is_err());
    // dec_ctx is 800 positions: the 801st token is an error, not an overflow.
    assert!(al.logits_for(&feats, &vec![5; 800]).is_ok());
    assert!(al.logits_for(&feats, &vec![5; 801]).is_err());
}

#[test]
fn rejects_bad_configs() {
    let text = std::fs::read_to_string(testdata().join("tiny_config.json")).unwrap();
    let good: serde_json::Value = serde_json::from_str(&text).unwrap();
    assert!(AlignerConfig::from_json(&good).is_ok());
    for (field, value) in [
        ("n_mels", serde_json::json!(128)),
        ("heads", serde_json::json!(5)),
        ("state", serde_json::json!(0)),
        ("enc_layers", serde_json::json!(0)),
        ("dec_layers", serde_json::json!(65)),
        ("vocab", serde_json::json!(799)),
        ("dec_ctx", serde_json::json!(0)),
    ] {
        let mut bad = good.clone();
        bad[field] = value.clone();
        assert!(
            AlignerConfig::from_json(&bad).is_err(),
            "{field}={value} accepted"
        );
    }
    AlignerConfig::megatts3().validate().unwrap();
    let file = SafetensorsFile::open(&testdata().join("tiny_weights.safetensors")).unwrap();
    assert!(Aligner::load(AlignerConfig::megatts3(), &file).is_err());
    assert_eq!(MAX_NEW_TOKENS, 768);
}

/// Real converted checkpoint on a real speech clip, against the reference's
/// own `align()` run with librosa's soxr resampler.
#[test]
fn real_checkpoint_matches_pytorch() {
    let (Some(model_dir), Some(golden)) = (
        std::env::var_os("TURBOSPARK_ALIGNER_MODEL"),
        std::env::var_os("TURBOSPARK_ALIGNER_GOLDEN"),
    ) else {
        eprintln!("skipped: TURBOSPARK_ALIGNER_MODEL / TURBOSPARK_ALIGNER_GOLDEN not set");
        return;
    };
    let golden = PathBuf::from(golden);
    let al = Aligner::open(Path::new(&model_dir)).unwrap();
    let want_stream = i32s(&golden, "r_stream.npy");
    let want_ph = i32s(&golden, "r_ph.npy");
    let want_tone = i32s(&golden, "r_tone.npy");
    let want_m2p = i32s(&golden, "r_mel2ph.npy");

    // 1. Same 16 kHz audio the reference fed its model: everything downstream
    //    of the resampler must agree exactly.
    let wav16 = f32s(&golden, "r_wav16.npy");
    let (mel, frames) = prompt_mel(&wav16).unwrap();
    let ref_mel = f32s(&golden, "r_mel.npy");
    let ref_frames = ref_mel.len() / 80;
    let mut worst = 0.0f32;
    for m in 0..80 {
        for t in 0..frames {
            worst = worst.max((mel[m * frames + t] - ref_mel[m * ref_frames + t]).abs());
        }
    }
    println!("real: mel (same audio) {frames} frames, max diff {worst:e}");
    assert!(worst < 2e-4, "mel diff {worst}");
    let feats = al.encode(&mel, frames).unwrap();
    let stream = al.generate(&feats, MAX_NEW_TOKENS).unwrap();
    println!(
        "real: {} tokens, reference {}",
        stream.len(),
        want_stream.len()
    );
    assert_eq!(
        stream, want_stream,
        "token stream from the reference's 16 kHz audio"
    );
    let got = align_tokens(&stream, frames).unwrap();
    assert_eq!(
        (got.phone, got.tone, got.mel2ph),
        (want_ph.clone(), want_tone.clone(), want_m2p.clone())
    );

    // 2. The crate's own resampler from the 24 kHz prompt: report how far the
    //    mel and the alignment drift from the soxr path.
    let wav24 = f32s(&golden, "r_wav24.npy");
    let padded = pad_prompt_audio(&wav24);
    assert_eq!(
        padded.len() as i32,
        i32s(&golden, "r_wav24_padded_len.npy")[0]
    );
    let wav16_rust = resample_for_aligner(&padded).unwrap();
    let (mel_r, frames_r) = prompt_mel(&wav16_rust).unwrap();
    let n = frames.min(frames_r);
    let mut mel_gap = 0.0f32;
    for m in 0..80 {
        for t in 0..n {
            mel_gap = mel_gap.max((mel_r[m * frames_r + t] - ref_mel[m * ref_frames + t]).abs());
        }
    }
    let feats_r = al.encode(&mel_r, frames_r).unwrap();
    let stream_r = al.generate(&feats_r, MAX_NEW_TOKENS).unwrap();
    let same_tokens = stream_r == want_stream;
    println!(
        "real: sinc-Hann resample: {frames_r} vs {frames} frames, mel gap {mel_gap:e}, identical tokens: {same_tokens}"
    );
    assert_eq!(
        frames_r, frames,
        "resampled length must match the reference"
    );
    // Measured on this clip: the same phone sequence, timestamps within one
    // 10 ms frame, and a small mel gap (the soxr filter is not reproduced).
    assert_eq!(
        stream_r.len(),
        want_stream.len(),
        "token count under the crate resampler"
    );
    let max_delta = stream_r
        .iter()
        .zip(&want_stream)
        .map(|(a, b)| (a - b).abs())
        .max()
        .unwrap();
    let aligned = align_tokens(&stream_r, frames_r).unwrap();
    println!(
        "real: max token delta {max_delta}, phones identical: {}",
        aligned.phone == want_ph
    );
    assert!(
        max_delta <= 1,
        "tokens moved by more than one frame: {max_delta}"
    );
    assert_eq!(
        aligned.phone, want_ph,
        "phone sequence under the crate resampler"
    );
    assert!(mel_gap < 0.05, "mel gap {mel_gap}");
}
